        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('website.contact_messages') AND c.contype = 'f' AND a.attname = 'website_id'
    ) THEN
        ALTER TABLE website.contact_messages ADD CONSTRAINT fk_contact_messages_website_id FOREIGN KEY (website_id) REFERENCES website.websites (id) ON DELETE CASCADE NOT VALID;
        BEGIN
            ALTER TABLE website.contact_messages VALIDATE CONSTRAINT fk_contact_messages_website_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_contact_messages_website_id left NOT VALID: stored rows of website.contact_messages reference missing rows';
        END;
    END IF;
END $$;

